mapper.select:
SELECT e.exam_id AS examId, e.title, e.start_time AS startTime, e.end_time AS endTime, e.status, u.nick_name AS creatorName, e.create_time AS createTime, (SELECT COUNT(*) FROM tb_user_exam ue WHERE ue.exam_id = e.exam_id) AS enterCount FROM tb_exam e LEFT JOIN tb_sys_user u ON e.create_by = u.user_id
AND e.title LIKE CONCAT('%', #{query.title}, '%')
AND e.start_time >= #{query.startTime}
AND e.end_time <= #{query.endTime}
ORDER BY e.create_time DESC, e.exam_id DESC
